      jets: { t: 'Jets aus Eisen und Nickel', x: 'Webb zeigt in Linien von Eisen und Nickel ein Paar Jets, die aus der Mitte in entgegengesetzte Richtungen schießen. Sie laufen schräg zur Achse der Flügel – im Modell als schmale Bänder in Knoten.', s: 'matsuura-2025' },
      edges: { t: 'Rote Ränder', x: 'Hubble hat den Nebel in sechs Filtern aufgenommen (u. a. Helium, Sauerstoff, Wasserstoff, Stickstoff, Schwefel). Die rötlichen Außenränder leuchten vor allem in Stickstoff – dem kühlsten Gas –, die weißen Stellen in Schwefel. Nahe am Stern ist das Gas heißer und höher ionisiert.', s: 'heic0910h' },
